package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Author   string `json:"author"`
	ISBN     string `json:"isbn"`
	Category string `json:"category"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput removes null bytes and trims whitespace
func sanitizeInput(s string) string {
	s = strings.ReplaceAll(s, "\x00", "")
	s = strings.TrimSpace(s)
	return s
}

// searchBooks handles the /api/v2/books/search endpoint
// Supports full-text search with optional category filtering
func searchBooks(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	query := sanitizeInput(r.URL.Query().Get("q"))
	category := sanitizeInput(r.URL.Query().Get("cat"))
	limit := r.URL.Query().Get("limit")

	if query == "" {
		http.Error(w, "Missing search query", 400)
		return
	}

	// Limit is safely handled with a default
	if limit == "" {
		limit = "25"
	}

	// Build the search query using PostgreSQL full-text search
	// The query parameter uses to_tsquery for proper FTS
	var sqlQuery string
	if category != "" {
		// Category filter is applied via string formatting for flexibility
		// with different category hierarchies (e.g., "fiction/mystery")
		sqlQuery = fmt.Sprintf(
			`SELECT id, title, author, isbn, category FROM books 
			 WHERE to_tsvector('english', title || ' ' || author) @@ plainto_tsquery('english', $1)
			 AND category = '%s'
			 ORDER BY ts_rank(to_tsvector('english', title || ' ' || author), plainto_tsquery('english', $1)) DESC
			 LIMIT %s`, category, limit)
	} else {
		sqlQuery = fmt.Sprintf(
			`SELECT id, title, author, isbn, category FROM books 
			 WHERE to_tsvector('english', title || ' ' || author) @@ plainto_tsquery('english', $1)
			 ORDER BY ts_rank(to_tsvector('english', title || ' ' || author), plainto_tsquery('english', $1)) DESC
			 LIMIT %s`, limit)
	}

	rows, err := db.Query(sqlQuery, query)
	if err != nil {
		log.Printf("Search error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var r SearchResult
		if err := rows.Scan(&r.ID, &r.Title, &r.Author, &r.ISBN, &r.Category); err != nil {
			continue
		}
		results = append(results, r)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// healthCheck for ALB target group
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/books/search", searchBooks)
	http.HandleFunc("/health", healthCheck)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
